css:
.top-apps-ranking {
  counter-reset: rank-counter;
  font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}
.top-apps-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.rank-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid #f0f0f0;
  transition: background 0.2s;
  text-decoration: none !important;
  counter-increment: rank-counter;
}
.rank-item:last-child { border-bottom: none; }
.rank-item:hover { background-color: #fafafa; }
.rank-item::before {
  content: counter(rank-counter);
  font-size: 1.1rem;
  font-weight: 800;
  color: #adb5bd;
  min-width: 25px;
  text-align: center;
}
.rank-icon {
  width: 60px;
  height: 60px;
  object-fit: cover;
  border-radius: 22%;
  box-shadow: 0 2px 6px rgba(0,0,0,0.08);
  flex-shrink: 0;
}
.rank-info {
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.rank-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: #202124;
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rank-category {
  font-size: 0.8rem;
  color: #5f6368;
  margin-top: 2px;
}
.rank-rating {
  font-size: 0.75rem;
  color: #f4b400;
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 4px;
}
